declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();if(!in_array($_SESSION['role'],['system_admin','sub_admin'],true)){http_response_code(403);exit('Audit logs are available to System Admins and Sub System Admins.');}
$page=max(1,(int)($_GET['page']??1));$perPage=40;$action=trim((string)($_GET['action']??''));$entity=trim((string)($_GET['entity']??''));$actor=trim((string)($_GET['actor']??''));$where=[];$params=[];if($action!==''){$where[]='l.action=?';$params[]=$action;}if($entity!==''){$where[]='l.entity_type=?';$params[]=$entity;}if($actor!==''){$where[]='(u.name LIKE ? OR u.email LIKE ? OR u.username LIKE ?)';array_push($params,"%$actor%","%$actor%","%$actor%");}$clause=$where?'WHERE '.implode(' AND ',$where):'';$db=db();$count=$db->prepare("SELECT COUNT(*) FROM audit_logs l LEFT JOIN users u ON u.id=l.actor_id $clause");$count->execute($params);$total=(int)$count->fetchColumn();$offset=($page-1)*$perPage;$q=$db->prepare("SELECT l.id,l.action,l.entity_type,l.entity_id,l.details,l.created_at,u.name actor_name,u.email,u.username FROM audit_logs l LEFT JOIN users u ON u.id=l.actor_id $clause ORDER BY l.created_at DESC LIMIT $perPage OFFSET $offset");$q->execute($params);$logs=$q->fetchAll();?><!doctype html>
