<div class="table-wrap audit-table-wrap"><table class="audit-table"><thead><tr><th scope="col">Date and time</th><th scope="col">Changed by</th><th scope="col">Action</th><th scope="col">Affected record</th><th scope="col">Details</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><time class="audit-time" datetime="<?=e($log['created_at'])?>"><strong><?=e(date('j M Y',strtotime($log['created_at'])))?></strong><span><?=e(date('H:i',strtotime($log['created_at'])))?></span></time></td><td><div class="audit-actor"><span class="audit-actor-avatar" aria-hidden="true"><?=e(strtoupper(substr($log['actor_name']?:'?',0,1)))?></span><span><strong><?=e($log['actor_name']?:'Deleted account')?></strong><small><?=e($log['email']?:($log['username']??'No sign-in ID'))?></small></span></div></td><td><span class="audit-action"><?=e(ucfirst(str_replace('_',' ',$log['action'])))?></span></td><td><span class="audit-record-type"><?=e(str_replace('_',' ',$log['entity_type']))?></span><strong class="audit-record-id">#<?=e((string)($log['entity_id']??'—'))?></strong></td><td><?php if($log['details']):?><details class="audit-details"><summary>View details</summary><p><?=e($log['details'])?></p></details><?php else:?><span class="audit-no-details">No additional details</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
